alter table public.physical_treasure_boxes add column if not exists content_options text[] not null default '{}'::text[];
alter table public.physical_treasure_boxes drop constraint if exists physical_treasure_boxes_content_options_check;
alter table public.physical_treasure_boxes add constraint physical_treasure_boxes_content_options_check check (content_options <@ array['digital_story','traveling_token','specialty_token','quest']::text[]);
create or replace function public.get_claimed_treasure_box_content_options(p_nfc_public_token uuid) returns text[] language sql stable security definer set search_path='' as $$ select ptb.content_options from public.physical_treasure_boxes ptb where ptb.nfc_public_token=p_nfc_public_token and ptb.owner_id=auth.uid() limit 1; $$;
create or replace function public.save_claimed_treasure_box_content_options(p_nfc_public_token uuid,p_content_options text[]) returns text[] language plpgsql security definer set search_path='' as $$ declare v_options text[]; v_invalid text[]; begin if auth.uid() is null then raise exception 'Authentication required'; end if; select coalesce(array_agg(distinct x order by x),'{}'::text[]) into v_options from unnest(coalesce(p_content_options,'{}'::text[])) x; select coalesce(array_agg(x),'{}'::text[]) into v_invalid from unnest(v_options) x where x not in ('digital_story','traveling_token','specialty_token','quest'); if cardinality(v_invalid)>0 then raise exception 'One or more Treasure Box content options are not supported'; end if; update public.physical_treasure_boxes ptb set content_options=v_options,updated_at=now() where ptb.nfc_public_token=p_nfc_public_token and ptb.owner_id=auth.uid() and ptb.claim_status='claimed'; if not found then raise exception 'Treasure Box not found or not owned by you'; end if; return v_options; end; $$;
revoke all on function public.get_claimed_treasure_box_content_options(uuid) from public; grant execute on function public.get_claimed_treasure_box_content_options(uuid) to authenticated;
revoke all on function public.save_claimed_treasure_box_content_options(uuid,text[]) from public; grant execute on function public.save_claimed_treasure_box_content_options(uuid,text[]) to authenticated;